body.script:
(function () {
    var width = parseInt(document.body.dataset.width, 10) || 576;
    function ticket(label) {
        var c = document.createElement("canvas");
        c.width = width; c.height = 360;
        var g = c.getContext("2d");
        g.fillStyle = "#fff"; g.fillRect(0, 0, c.width, c.height);
        g.strokeStyle = "#000"; g.lineWidth = 4; g.strokeRect(2, 2, c.width - 4, c.height - 4);
        g.fillStyle = "#000"; g.textAlign = "center";
        g.font = "bold 44px sans-serif"; g.fillText("TEST " + label, c.width / 2, 80);
        g.font = "28px sans-serif";
        g.fillText("RawBT - " + (width === 576 ? "80 mm" : "58 mm"), c.width / 2, 140);
        g.fillText(new Date().toLocaleString(), c.width / 2, 190);
        for (var x = 0; x !== Math.ceil(c.width / 24) * 24; x += 24) { g.fillRect(x, 240, 12, 40); }
        g.font = "22px sans-serif";
        g.fillText("The frame must be complete on the paper", c.width / 2, 330);
        return window.XbRawBT.toBase64(window.XbRawBT.canvasToEscPos(c, width));
    }
    var log = document.getElementById("log");
    document.querySelectorAll("button").forEach(function (btn) {
        btn.addEventListener("click", function () {
            var label = btn.querySelector("b").textContent;
            var delay = parseInt(btn.dataset.delay, 10);
            var b64 = ticket(label);
            log.textContent = "Sending " + label + (delay ? " in 3 s..." : "...");
            setTimeout(function () {
                window.XbRawBT.send(b64, btn.dataset.method);
                log.textContent = "Sent " + label + ".";
            }, delay);
        });
    });
})();
